1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/idecode.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This RTL file specifies how instructions are to be decoded
8	//		into their underlying meanings.
9	//
10	// Creator:	Dan Gisselquist, Ph.D.
11	//		Gisselquist Technology, LLC
12	//
13	////////////////////////////////////////////////////////////////////////////////
14	// }}}
15	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
16	// {{{
17	// This program is free software (firmware): you can redistribute it and/or
18	// modify it under the terms of the GNU General Public License as published
19	// by the Free Software Foundation, either version 3 of the License, or (at
20	// your option) any later version.
21	//
22	// This program is distributed in the hope that it will be useful, but WITHOUT
23	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
24	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
25	// for more details.
26	//
27	// You should have received a copy of the GNU General Public License along
28	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
29	// target there if the PDF file isn't present.)  If not, see
30	// <http://www.gnu.org/licenses/> for a copy.
31	// }}}
32	// License:	GPL, v3, as defined and found on www.gnu.org,
33	// {{{
34	//		http://www.gnu.org/licenses/gpl.html
35	//
36	////////////////////////////////////////////////////////////////////////////////
37	//
38	`default_nettype	none
39	// }}}
40	module	idecode #(
41			// {{{
42			parameter		ADDRESS_WIDTH=24,
43			parameter	[0:0]	OPT_MPY = 1'b1,
44			parameter	[0:0]	OPT_SHIFTS = 1'b1,
45			parameter	[0:0]	OPT_EARLY_BRANCHING = 1'b1,
46			parameter	[0:0]	OPT_PIPELINED = 1'b1,
47			parameter	[0:0]	OPT_DIVIDE = (OPT_PIPELINED),
48			parameter	[0:0]	OPT_FPU    = 1'b0,
49			parameter	[0:0]	OPT_CIS    = 1'b1,
50			parameter	[0:0]	OPT_LOCK   = (OPT_PIPELINED),
51			parameter	[0:0]	OPT_OPIPE  = (OPT_PIPELINED),
52			parameter	[0:0]	OPT_SIM    = 1'b0,
53			parameter	[0:0]	OPT_SUPPRESS_NULL_BRANCHES = 1'b0,
54			parameter	[0:0]	OPT_USERMODE = 1'b1,
55			parameter	[0:0]	OPT_LOWPOWER = 1'b0,
56			localparam		AW = ADDRESS_WIDTH
57			// }}}
58		) (
59			// {{{
60			input	wire		i_clk, i_reset, i_ce, i_stalled,
61			input	wire [31:0]	i_instruction,
62			input	wire		i_gie,
63			input	wire [(AW+1):0]	i_pc,
64			input	wire		i_pf_valid, i_illegal,
65			output	wire		o_valid, o_phase,
66			output	reg		o_illegal,
67			output	reg	[(AW+1):0]	o_pc,
68			output	reg	[6:0]	o_dcdR, o_dcdA, o_dcdB,
69			output	wire	[4:0]	o_preA, o_preB,
70			output	wire	[31:0]	o_I,
71			output	reg		o_zI,
72			output	reg	[3:0]	o_cond,
73			output	reg		o_wF,
74			output	reg	[3:0]	o_op,
75			output	reg		o_ALU, o_M, o_DV, o_FP, o_break,
76			output	reg		o_lock,
77			output	reg		o_wR, o_rA, o_rB,
78			output	wire		o_early_branch, o_early_branch_stb,
79			output	wire	[(AW+1):0]	o_branch_pc,
80			output	wire		o_ljmp,
81			output	wire		o_pipe,
82			output	reg		o_sim,
83			output	reg	[22:0]	o_sim_immv
84	`ifdef	FORMAL
85			, output	reg	[31:0]	f_insn_word,
86			output	reg		f_insn_gie,
87			output	wire		f_insn_is_pipeable
88	`endif
89			// }}}
90		);
91	
92		// Declarations
93		// {{{
94		localparam	[3:0]	CPU_SP_REG = 4'hd,
95					CPU_CC_REG = 4'he,
96					CPU_PC_REG = 4'hf;
97		localparam		CISBIT    = 31,
98					CISIMMSEL = 23,
99					IMMSEL    = 18;
100	
101		wire	[4:0]	w_op;
102		wire		w_ldi, w_mov, w_cmptst, w_ldilo, w_ALU, w_brev,
103				w_noop, w_lock, w_sim, w_break, w_special, w_add, w_mpy;
104		wire	[4:0]	w_dcdR, w_dcdB, w_dcdA;
105		wire		w_dcdR_pc, w_dcdR_cc;
106		wire		w_dcdA_pc, w_dcdA_cc;
107		wire		w_dcdB_pc, w_dcdB_cc;
108		wire	[3:0]	w_cond;
109		wire		w_wF, w_mem, w_sto, w_div, w_fpu;
110		wire		w_wR, w_rA, w_rB, w_wR_n;
111		wire		w_ljmp, w_ljmp_dly, w_cis_ljmp;
112		wire	[31:0]	iword;
113		wire		pf_valid;
114	
115		reg	[14:0]	r_nxt_half;
116		reg	[4:0]	w_cis_op;
117		reg	[22:0]	r_I, w_fullI;
118		wire	[22:0]	w_I;
119		wire		w_Iz;
120	
121		reg	[1:0]	w_immsrc;
122		reg		r_valid;
123		wire		insn_is_pipeable, illegal_shift;
124		// }}}
125	
126		assign	pf_valid = (i_pf_valid)&&(!o_early_branch_stb);
127	
128		// iword
129		// {{{
130		generate if (OPT_CIS)
131		begin : SET_IWORD
132	
133			assign	iword = (o_phase)
134					// set second half as a NOOP ... but really
135					// shouldn't matter
136				? { 1'b1, r_nxt_half[14:0], i_instruction[15:0] }
137				: i_instruction;
138		end else begin : CLR_IWORD
139			assign	iword = { 1'b0, i_instruction[30:0] };
140	
141			// verilator coverage_off
142			// verilator lint_off UNUSED
143			wire		unused_nxt_half;
144			assign		unused_nxt_half = &{ 1'b0, r_nxt_half };
145			// verilator lint_on  UNUSED
146			// verilator coverage_on
147		end endgenerate
148		// }}}
149	
150		// w_ljmp, w_cis_ljmp : Long jump early branching
151		// {{{
152		generate
153		if (OPT_EARLY_BRANCHING)
154		begin : GEN_CIS_LONGJUMP
155			if (OPT_CIS)
156			begin : CIS_EARLY_BRANCHING
157	
158				assign	w_cis_ljmp = (o_phase)&&(iword[31:16] == 16'hfcf8);
159	
160			end else begin : NOCIS_EARLY_BRANCH
161	
162				assign	w_cis_ljmp = 1'b0;
163	
164			end
165	
166			assign	w_ljmp = (iword == 32'h7c87c000);
167	
168		end else begin : NO_CIS_JUMPING
169	
170			assign	w_cis_ljmp = 1'b0;
171			assign	w_ljmp = 1'b0;
172		end endgenerate
173		// }}}
174	
175		// w_cis_op : Get the opcode
176		// {{{
177		generate if (OPT_CIS)
178		begin : GEN_CIS_OP
179	
180			always @(*)
181			if (!iword[CISBIT])
182				w_cis_op = iword[26:22];
183			else case(iword[26:24])
184			3'h0: w_cis_op = 5'h00;	// SUB
185			3'h1: w_cis_op = 5'h01;	// AND
186			3'h2: w_cis_op = 5'h02;	// ADD
187			3'h3: w_cis_op = 5'h10;	// CMP
188			3'h4: w_cis_op = 5'h12;	// LW
189			3'h5: w_cis_op = 5'h13;	// SW
190			3'h6: w_cis_op = 5'h18;	// LDI
191			3'h7: w_cis_op = 5'h0d;	// MOV
192			endcase
193	
194		end else begin : GEN_NOCIS_OP
195	
196			always @(*)
197				w_cis_op = w_op;
198	
199		end endgenerate
200		// }}}
201	
202		// Decode instructions
203		// {{{
204		assign	w_op= iword[26:22];
205		assign	w_mov    = (w_cis_op      == 5'h0d);
206		assign	w_ldi    = (w_cis_op[4:1] == 4'hc);
207		assign	w_brev   = (w_cis_op      == 5'h08);
208		assign	w_mpy    = (w_cis_op[4:1] == 4'h5)||(w_cis_op[4:0]==5'h0c);
209		assign	w_cmptst = (w_cis_op[4:1] == 4'h8);
210		assign	w_ldilo  = (w_cis_op[4:0] == 5'h09);
211		assign	w_ALU    = (!w_cis_op[4]) // anything with [4]==0, but ...
212					&&(w_cis_op[3:1] != 3'h7); // not the divide
213		assign	w_add    = (w_cis_op[4:0] == 5'h02);
214		assign	w_mem    = (w_cis_op[4:3] == 2'b10)&&(w_cis_op[2:1] !=2'b00);
215		assign	w_sto    = (w_mem)&&( w_cis_op[0]);
216		assign	w_div    = (!iword[CISBIT])&&(w_op[4:1] == 4'h7);
217		assign	w_fpu    = (!iword[CISBIT])&&(w_op[4:3] == 2'b11)
218					&&(w_dcdR[3:1] != 3'h7)
219					&&(w_op[2:1] != 2'b00);
220		// If the result register is either CC or PC, and this would otherwise
221		// be a floating point instruction with floating point opcode of 0,
222		// then this is a NOOP.
223		assign	w_special= (!iword[CISBIT])&&(w_dcdR[3:1]==3'h7)
224				&&(w_op[4:2] == 3'b111);
225		assign	w_break = (w_special)&&(w_op[4:0]==5'h1c);
226		assign	w_lock  = (w_special)&&(w_op[4:0]==5'h1d);
227		assign	w_sim   = (w_special)&&(w_op[4:0]==5'h1e);
228		assign	w_noop  = (w_special)&&(w_op[4:1]==4'hf); // Must include w_sim
229	`ifdef	FORMAL
230		always @(*)
231			assert(!w_special || !w_fpu);
232	`endif
233		// }}}
234	
235		// w_dcdR, w_dcdA
236		// {{{
237		// What register will we be placing results into (if at all)?
238		//
239		// Two parts to the result register: the register set, given for
240		// moves in iword[18] but only for the supervisor, and the other
241		// four bits encoded in the instruction.
242		//
243		assign	w_dcdR = { ((!iword[CISBIT])&&(OPT_USERMODE)&&(w_mov)&&(!i_gie))?iword[IMMSEL]:i_gie,
244					iword[30:27] };
245	
246		// 0 LUTs
247		assign	w_dcdA = w_dcdR;	// on ZipCPU, A is always result reg
248		// 0 LUTs
249		assign	w_dcdA_pc = w_dcdR_pc;
250		assign	w_dcdA_cc = w_dcdR_cc;
251		// 2 LUTs, 1 delay each
252		assign	w_dcdR_pc = (w_dcdR == {i_gie, CPU_PC_REG});
253		assign	w_dcdR_cc = (w_dcdR == {i_gie, CPU_CC_REG});
254		// }}}
255	
256		// dcdB - What register is used in the opB?
257		// {{{
258		assign w_dcdB[4] = ((!iword[CISBIT])&&(w_mov)&&(OPT_USERMODE)&&(!i_gie))?iword[13]:i_gie;
259		assign w_dcdB[3:0]= (iword[CISBIT])
260					? (((!iword[CISIMMSEL])&&(iword[26:25]==2'b10))
261						? CPU_SP_REG : iword[22:19])
262					: iword[17:14];
263	
264		// 2 LUTs, 1 delays each
265		assign	w_dcdB_pc = (w_rB)&&(w_dcdB[3:0] == CPU_PC_REG);
266		assign	w_dcdB_cc = (w_rB)&&(w_dcdB[3:0] == CPU_CC_REG);
267		// }}}
268	
269		// w_cond
270		// {{{
271		// Under what condition will we execute this instruction?  Only the
272		// load immediate instruction and the CIS instructions are completely
273		// unconditional.  Well ... not quite.  The BREAK, LOCK, and SIM/NOOP
274		// instructions are also unconditional.
275		//
276		assign	w_cond = ((w_ldi)||(w_special)||(iword[CISBIT])) ? 4'h8 :
277				{ (iword[21:19]==3'h0), iword[21:19] };
278		// }}}
279	
280		// rA - do we need to read register A?
281		// {{{
282		assign	w_rA = // Floating point reads reg A
283				(w_fpu)
284				// Divide's read A
285				||(w_div)
286				// ALU ops read A,
287				//	except for MOV's and BREV's which don't
288				||((w_ALU)&&(!w_brev)&&(!w_mov))
289				// STO's read A
290				||(w_sto)
291				// Test/compares
292				||(w_cmptst);
293		// }}}
294	
295		// rB -- do we read a register for operand B?
296		// {{{
297		// Specifically, do we add the registers value to the immediate to
298		// create opB?
299		assign	w_rB     = (w_mov)
300					||((!iword[CISBIT])&&(iword[IMMSEL])&&(!w_ldi)&&(!w_special))
301					||(( iword[CISBIT])&&(iword[CISIMMSEL])&&(!w_ldi))
302					// If using compressed instruction sets,
303					// we *always* read on memory operands.
304					||(( iword[CISBIT])&&(w_mem));
305		// }}}
306	
307		// wR -- will we be writing our result back?
308		// {{{
309		// wR_n = !wR
310		// All but STO, NOOP/BREAK/LOCK, and CMP/TST write back to w_dcdR
311		assign	w_wR_n   = (w_sto)
312					||(w_special)
313					||(w_cmptst);
314		assign	w_wR     = !w_wR_n;
315		// }}}
316		//
317		// wF -- do we write flags when we are done?
318		// {{{
319		assign	w_wF     = (w_cmptst)
320				||((w_cond[3])&&(w_fpu||w_div
321					||((w_ALU)&&(!w_mov)&&(!w_ldilo)&&(!w_brev)
322						&&(w_dcdR[3:1] != 3'h7))));
323		// }}}
324	
325		// w_immsrc - where does the immediate value come from
326		// {{{
327		// Bottom 13 bits: no LUT's
328		// w_dcd[12: 0] -- no LUTs
329		// w_dcd[   13] -- 2 LUTs
330		// w_dcd[17:14] -- (5+i0+i1) = 3 LUTs, 1 delay
331		// w_dcd[22:18] : 5 LUTs, 1 delay (assuming high bit is o/w determined)
332		always @(*)
333		if (w_ldi)
334			w_immsrc = 0;
335		else if (w_mov)
336			w_immsrc = 1;
337		else if (!iword[IMMSEL])
338			w_immsrc = 2;
339		else // if (!iword[IMMSEL])
340			w_immsrc = 3;
341		// }}}
342	
343		// w_fullI -- extracting the immediate value from the insn word
344		// {{{
345		always @(*)
346		case(w_immsrc)
347		2'b00: w_fullI = { iword[22:0] }; // LDI
348		2'b01: w_fullI = { {(23-13){iword[12]}}, iword[12:0] }; // MOV
349		2'b10: w_fullI = { {(23-18){iword[17]}}, iword[17:0] }; // Immediate
350		2'b11: w_fullI = { {(23-14){iword[13]}}, iword[13:0] }; // Reg + Imm
351		endcase
352		/*
353		assign	w_fullI = (w_ldi) ? { iword[22:0] } // LDI
354				// MOVE immediates have one less bit
355				:((w_mov) ?{ {(23-13){iword[12]}}, iword[12:0] }
356				// Normal Op-B immediate ... 18 or 14 bits
357				:((!iword[IMMSEL]) ? { {(23-18){iword[17]}}, iword[17:0] }
358				: { {(23-14){iword[13]}}, iword[13:0] }
359				));
360		*/
361		// }}}
362	
363		// w_I and w_Iz: Immediate value decoding
364		// {{{
365		generate if (OPT_CIS)
366		begin : GEN_CIS_IMMEDIATE
367			wire	[7:0]	w_halfI, w_halfbits;
368	
369			assign	w_halfbits = iword[CISIMMSEL:16];
370			assign	w_halfI = (iword[26:24]==3'h6) ? w_halfbits[7:0] // 8'b for LDI
371					:(w_halfbits[7])?
372						{ {(6){w_halfbits[2]}}, w_halfbits[1:0]}
373						:{ w_halfbits[6], w_halfbits[6:0] };
374			assign	w_I  = (iword[CISBIT])
375					? {{(23-8){w_halfI[7]}}, w_halfI }
376					: w_fullI;
377	
378		end else begin : GEN_NOCIS_IMMEDIATE
379	
380			assign	w_I  = w_fullI;
381	
382		end endgenerate
383	
384		assign	w_Iz = (w_I == 0);
385		// }}}
386	
387		// o_phase
388		// {{{
389		// The o_phase parameter is special.  It needs to let the software
390		// following know that it cannot break/interrupt on an o_phase asserted
391		// instruction, lest the break take place between the first and second
392		// half of a CIS instruction.  To do this, o_phase must be asserted
393		// when the first instruction half is valid, but not asserted on either
394		// a 32-bit instruction or the second half of a 2x16-bit instruction.
395		generate if (OPT_CIS)
396		begin : GEN_CIS_PHASE
397			// {{{
398			reg	r_phase;
399	
400			// Phase is '1' on the first instruction of a two-part set
401			// But, due to the delay in processing, it's '1' when our
402			// output is valid for that first part, but that'll be the
403			// same time we are processing the second part ... so it may
404			// look to us like a '1' on the second half of processing.
405	
406			// When no instruction is in the pipe, phase is zero
407			initial	r_phase = 1'b0;
408			always @(posedge i_clk)
409			if (i_reset || w_ljmp_dly)
410				r_phase <= 1'b0;
411			else if ((i_ce)&&(pf_valid))
412			begin
413				if (o_phase)
414					// CIS instructions only have two parts.  On
415					// the second part (o_phase is true), return
416					// back to the first
417					r_phase <= 0;
418				else
419					r_phase <= (i_instruction[CISBIT])&&(!i_illegal);
420			end else if (i_ce)
421				r_phase <= 1'b0;
422	
423			assign	o_phase = r_phase;
424			// }}}
425		end else begin : NO_CIS
426			// {{{
427			assign	o_phase = 1'b0;
428			// }}}
429		end endgenerate
430		// }}}
431	
432		// illegal_shift
433		// {{{
434		generate if (OPT_SHIFTS)
435		begin : LEGAL_SHIFTS
436			assign	illegal_shift = 1'b0;
437		end else begin : GEN_ILLEGAL_SHIFT
438			reg	r_illegal_shift;
439	
440			always @(*)
441			begin
442				r_illegal_shift = 1'b1;
443				if (i_instruction[CISBIT])
444					r_illegal_shift = 1'b0;
445				else if ((i_instruction[26:22] != 5'h5)
446					&&(i_instruction[26:22] != 5'h6)
447					&&(i_instruction[26:22] != 5'h7))
448					r_illegal_shift = 1'b0;
449				else if (!i_instruction[18]
450						&& (i_instruction[17:0] == 18'h1))
451					r_illegal_shift = 1'b0;
452			end
453	
454			assign	illegal_shift = r_illegal_shift;
455		end endgenerate
456		// }}}
457	
458		// o_illegal
459		// {{{
460		initial	o_illegal = 1'b0;
461		always @(posedge i_clk)
462		if (i_reset)
463			o_illegal <= 1'b0;
464		else if (i_ce && o_phase)
465		begin
466			// {{{
467			o_illegal <= o_illegal;
468			//  Cannot happen in compressed word ...
469			// 1. multiply op-codes
470			// 2. divide opcodes
471			// 3. FPU opcodes
472			// 4. special opcodes
473			// }}}
474		end else if (i_ce && i_pf_valid)
475		begin
476			// {{{
477			o_illegal <= 1'b0;
478	
479			if (illegal_shift)
480				o_illegal <= 1'b1;
481	
482			if ((!OPT_CIS)&&(i_instruction[CISBIT]))
483				o_illegal <= 1'b1;
484			if ((!OPT_MPY)&&(w_mpy))
485				o_illegal <= 1'b1;
486	
487			if ((!OPT_DIVIDE)&&(w_div))
488				o_illegal <= 1'b1;
489			else if ((OPT_DIVIDE)&&(w_div)&&(w_dcdR[3:1]==3'h7))
490				o_illegal <= 1'b1;
491	
492	
493			if ((!OPT_FPU)&&(w_fpu))
494				o_illegal <= 1'b1;
495	
496			if ((!OPT_SIM)&&(w_sim))
497			// Simulation instructions on real hardware should
498			// always cause an illegal instruction error
499				o_illegal <= 1'b1;
500	
501			// There are two (missing) special instructions, after
502			// BREAK, LOCK, SIM, and NOOP.  These are special if their
503			// (unused-result) register is either the PC or CC register.
504			//
505			// These should cause an illegal instruction error
506			if ((w_dcdR[3:1]==3'h7)&&(w_cis_op[4:1]==4'b1101))
507				o_illegal <= 1'b1;
508	
509			// If the lock function isn't implemented, this should
510			// also cause an illegal instruction error
511			if ((!OPT_LOCK)&&(w_lock))
512				o_illegal <= 1'b1;
513	
514			// Bus errors always create illegal instructions
515			if (i_illegal)
516				o_illegal <= 1'b1;
517			// }}}
518		end
519		// }}}
520	
521		// o_pc
522		// {{{
523		initial	o_pc = 0;
524		always @(posedge i_clk)
525		if ((i_ce)&&((o_phase)||(i_pf_valid)))
526		begin
527			o_pc[0] <= 1'b0;
528	
529			if (OPT_CIS)
530			begin
531				if (iword[CISBIT])
532				begin
533					if (o_phase)
534						o_pc[AW+1:1] <= o_pc[AW+1:1] + 1'b1;
535					else
536						o_pc <= { i_pc[AW+1:2], 1'b1, 1'b0 };
537				end else begin
538					// The normal, non-CIS case
539					o_pc <= { i_pc[AW+1:2] + 1'b1, 2'b00 };
540				end
541			end else begin
542				// The normal, non-CIS case
543				o_pc <= { i_pc[AW+1:2] + 1'b1, 2'b00 };
544			end
545		end
546		// }}}
547	
548		// Generate output products
549		// {{{
550		initial	o_dcdR = 0;
551		initial	o_dcdA = 0;
552		initial	o_dcdB = 0;
553		initial	o_DV   = 0;
554		initial	o_FP   = 0;
555		initial	o_lock = 0;
556		initial	o_sim = 1'b0;
557		initial	o_sim_immv = 0;
558		// r_I, o_zI, o_wR, o_rA, o_rB, o_dcdR, o_dcdA, o_dcdB
559		always @(posedge i_clk)
560		if (i_ce)
561		begin
562			// {{{
563			// o_cond, o_wF
564			// {{{
565			// Under what condition will we execute this
566			// instruction?  Only the load immediate instruction
567			// is completely unconditional.
568			o_cond <= w_cond;
569			// Don't change the flags on conditional instructions,
570			// UNLESS: the conditional instruction was a CMP
571			// or TST instruction.
572			o_wF <= w_wF;
573			// }}}
574	
575			// o_op
576			// {{{
577			// Record what operation/op-code (4-bits) we are doing
578			//	Note that LDI magically becomes a MOV
579			// 	instruction here.  That way it's a pass through
580			//	the ALU.  Likewise, the two compare instructions
581			//	CMP and TST becomes SUB and AND here as well.
582			// We keep only the bottom four bits, since we've
583			// already done the rest of the decode necessary to
584			// settle between the other instructions.  For example,
585			// o_FP plus these four bits uniquely defines the FP
586			// instruction, o_DV plus the bottom of these defines
587			// the divide, etc.
588			o_op <= w_cis_op[3:0];
589			if ((w_ldi)||(w_noop)||(w_lock))
590				o_op <= 4'hd;
591			// }}}
592	
593			o_dcdR <= { w_dcdR_cc, w_dcdR_pc, w_dcdR};
594			o_dcdA <= { w_dcdA_cc, w_dcdA_pc, w_dcdA};
595			o_dcdB <= { w_dcdB_cc, w_dcdB_pc, w_dcdB};
596			o_wR  <= w_wR;
597			o_rA  <= w_rA;
598			o_rB  <= w_rB;
599			r_I    <= w_I;
600			o_zI   <= w_Iz;
601	
602			// o_ALU, o_M, o_DV, o_FP
603			// {{{
604			// Turn a NOOP into an ALU operation--subtract in
605			// particular, although it doesn't really matter as long
606			// as it doesn't take longer than one clock.  Note
607			// also that this depends upon not setting any registers
608			// or flags, which should already be true.
609			o_ALU  <=  (w_ALU)||(w_ldi)||(w_cmptst)||(w_noop)
610					||((!OPT_LOCK)&&(w_lock));
611			o_M    <=  w_mem;
612			o_DV   <=  (OPT_DIVIDE)&&(w_div);
613			o_FP   <=  (OPT_FPU)&&(w_fpu);
614			// }}}
615	
616			// o_break, o_lock
617			// {{{
618			o_break <= w_break;
619			o_lock  <= (OPT_LOCK)&&(w_lock);
620			// }}}
621	
622			if (OPT_CIS)
623				r_nxt_half <= { iword[14:0] };
624			else
625				r_nxt_half <= 0;
626	
627			// o_sim, o_sim_immv -- simulation instructions vs NOOPs
628			// {{{
629			if (OPT_SIM)
630			begin
631				// Support the SIM instruction(s)
632				o_sim <= (w_sim)||(w_noop);
633				o_sim_immv <= iword[22:0];
634				if (OPT_LOWPOWER && !w_sim && !w_noop)
635					o_sim_immv <= 0;
636			end else begin
637				o_sim <= 1'b0;
638				o_sim_immv <= 0;
639			end
640			// }}}
641			// }}}
642		end
643		// }}}
644	
645		assign	o_preA = w_dcdA;
646		assign	o_preB = w_dcdB;
647	
648		// o_early_branch, o_early_branch_stb, o_branch_pc
649		// {{{
650		generate if (OPT_EARLY_BRANCHING)
651		begin : GEN_EARLY_BRANCH_LOGIC
652			// {{{
653			reg			r_early_branch, r_early_branch_stb,
654						r_ljmp;
655			reg	[(AW+1):0]	r_branch_pc;
656			wire			w_add_to_pc;
657	
658			initial r_ljmp = 1'b0;
659			always @(posedge i_clk)
660			if (i_reset)
661				r_ljmp <= 1'b0;
662			else if (i_ce)
663			begin
664				if ((r_ljmp)&&(pf_valid))
665					r_ljmp <= 1'b0;
666				else if (o_early_branch_stb)
667					r_ljmp <= 1'b0;
668				else if (pf_valid)
669				begin
670					if ((OPT_CIS)&&(iword[CISBIT]))
671						r_ljmp <= w_cis_ljmp;
672					else
673						r_ljmp <= (w_ljmp);
674				end else if ((OPT_CIS)&&(o_phase)&&(iword[CISBIT]))
675					r_ljmp <= w_cis_ljmp;
676			end
677			assign	o_ljmp = r_ljmp;
678	
679			assign	w_add_to_pc = (!o_phase
680					&& (!OPT_CIS || !i_instruction[CISBIT])
681					&& (i_instruction[30:27]==CPU_PC_REG)	// Rd=PC
682					&& (i_instruction[26:22] == 5'h02)	// ADD
683					&& (i_instruction[21:19]==3'h0)		// NONE
684					&& !i_instruction[IMMSEL]);
685	
686			initial	r_early_branch     = 1'b0;
687			initial	r_early_branch_stb = 1'b0;
688			always @(posedge i_clk)
689			if (i_reset)
690			begin
691				r_early_branch     <= 1'b0;
692				r_early_branch_stb <= 1'b0;
693			end else if (i_ce && pf_valid)
694			begin
695				if (r_ljmp)
696				begin
697					// LW (PC),PC
698					r_early_branch     <= 1'b1;
699					r_early_branch_stb <= 1'b1;
700				end else if (w_add_to_pc)
701				begin
702					// Add x,PC
703					r_early_branch     <= 1'b1;
704					r_early_branch_stb <= (!OPT_SUPPRESS_NULL_BRANCHES)
705						|| (i_instruction[IMMSEL-1:0] != 0);
706				// LDI #x,PC is no longer supported
707				end else begin
708					r_early_branch <= 1'b0;
709					r_early_branch_stb <= 1'b0;
710				end
711			end else begin
712				r_early_branch_stb <= 1'b0;
713				if (i_ce)
714					r_early_branch     <= 1'b0;
715			end
716	
717			initial	r_branch_pc = 0;
718			always @(posedge i_clk)
719			if (OPT_LOWPOWER && i_reset)
720				r_branch_pc <= 0;
721			else if (i_ce)
722			begin
723				if (r_ljmp)
724					r_branch_pc <= { iword[(AW+1):2],
725							2'b00 };
726				else if (!OPT_LOWPOWER || w_add_to_pc)
727				begin
728					// Add x,PC
729					r_branch_pc[AW+1:2] <= i_pc[AW+1:2]
730						+ {{(AW-15){i_instruction[17]}},
731								i_instruction[16:2]}
732						+ {{(AW-1){1'b0}},1'b1};
733					r_branch_pc[1:0] <= 2'b00;
734				end else if (OPT_LOWPOWER)
735					r_branch_pc <= 0;
736	
737				if (OPT_LOWPOWER && !pf_valid)
738					r_branch_pc <= 0;
739			end
740	
741			assign	w_ljmp_dly         = r_ljmp;
742			assign	o_early_branch     = r_early_branch;
743			assign	o_early_branch_stb = r_early_branch_stb;
744			assign	o_branch_pc        = r_branch_pc;
745	`ifdef	FORMAL
746			always @(*)
747			if (OPT_LOWPOWER && !r_early_branch)
748				assert(r_branch_pc == 0);
749	`endif
750			// }}}
751		end else begin : NO_EARLY_BRANCHING
752			// {{{
753			assign	w_ljmp_dly         = 1'b0;
754			assign	o_early_branch     = 1'b0;
755			assign	o_early_branch_stb = 1'b0;
756			assign	o_branch_pc = {(AW+2){1'b0}};
757			assign	o_ljmp = 1'b0;
758	
759			// verilator coverage_off
760			// verilator lint_off UNUSED
761			wire	early_branch_unused;
762			assign	early_branch_unused = &{ 1'b0, w_add };
763			// verilator lint_on  UNUSED
764			// verilator coverage_on
765			// }}}
766		end endgenerate
767		// }}}
768	
769		// o_pipe
770		// {{{
771		// To be a pipeable operation there must be ...
772		//	1. Two valid adjacent instructions
773		//	2. Both must be memory operations, of the same time (both lods
774		//		or both stos)
775		//	3. Both must use the same register base address
776		//	4. Both must be to the same address, or the address incremented
777		//		by one
778		// Note that we're not using iword here ... there's a lot of logic
779		// taking place, and it's only valid if the new word is not compressed.
780		//
781		generate if (OPT_OPIPE)
782		begin : GEN_OPIPE
783			// {{{
784			reg	r_pipe, r_insn_is_pipeable;
785	
786			// Pipeline logic is too extreme for a single clock.
787			// Let's break it into two clocks, using r_insn_is_pipeable
788			// If this function is true, then the instruction associated
789			// with the current output *may* have a pipeable instruction
790			// following it.
791			//
792			initial	r_insn_is_pipeable = 1'b0;
793			always @(posedge i_clk)
794			if (i_reset)
795				r_insn_is_pipeable <= 1'b0;
796			else if ((i_ce)&&((!pf_valid)||(i_illegal))&&(!o_phase))
797				// Pipeline bubble, can't pipe through it
798				r_insn_is_pipeable <= 1'b0;
799			else if (o_ljmp)
800				r_insn_is_pipeable <= 1'b0;
801			else if ((i_ce)&&((!OPT_CIS)&&(i_instruction[CISBIT])))
802				r_insn_is_pipeable <= 1'b0;
803			else if (i_ce)
804			begin	// This is a valid instruction
805				r_insn_is_pipeable <= (w_mem)&&(w_rB)
806					// PC (and CC) registers can change
807					// underneath us.  Therefore they cannot
808					// be used as a base register for piped
809					// memory ops
810					&&(w_dcdB[3:1] != 3'h7)
811					// Writes to PC or CC will destroy any
812					// possibility of pipeing--since they
813					// could create a jump
814					&&(w_dcdR[3:1] != 3'h7)
815					//
816					// Loads landing in the current address
817					// pointer register are not allowed,
818					// as they could then be used to violate
819					// our rule(s)
820					&&((w_cis_op[0])||(w_dcdB != w_dcdA));
821			end // else
822				// The pipeline is stalled
823	
824			assign	insn_is_pipeable = r_insn_is_pipeable;
825	
826			initial	r_pipe = 1'b0;
827			always @(posedge i_clk)
828			if (i_reset)
829				r_pipe <= 1'b0;
830			else if (i_ce)
831				r_pipe <= ((pf_valid)||(o_phase))
832					// The last operation must be capable of
833					// being followed by a pipeable memory op
834					&&(r_insn_is_pipeable)
835					// Both must be memory operations
836					&&(w_mem)
837					// Both must be writes, or both stores
838					&&(o_op[0] == w_cis_op[0])
839					// Both must be register ops
840					&&(w_rB)
841					// Both must use the same register for B
842					&&(w_dcdB[3:0] == o_dcdB[3:0]);
843			//		// CC or PC registers are not valid addresses
844			//		//   Captured above
845			//		// But ... the result can never be B
846			//		//   Captured above
847			//		//
848			//		// Reads to CC or PC not allowed
849			//		// &&((o_op[0])||(w_dcdR[3:1] != 3'h7))
850			//		// Prior-reads to CC or PC not allowed
851			//		//   Captured above
852			//		// Same condition, or no condition now
853			//		&&((w_cond[2:0]==o_cond[2:0])
854			//			||(w_cond[2:0] == 3'h0));
855			//		// Same or incrementing immediate
856			//		&&(w_I[22]==r_I[22]);
857			assign o_pipe = r_pipe;
858			// }}}
859		end else begin : GEN_NO_PIPE
860			// {{{
861			assign	o_pipe = 1'b0;
862			assign	insn_is_pipeable = 1'b0;
863	
864			// verilator coverage_off
865			// verilator lint_off UNUSED
866			wire	unused_pipable;
867			assign	unused_pipable = &{ 1'b0, insn_is_pipeable };
868			// verilator lint_on  UNUSED
869			// verilator coverage_on
870			// }}}
871		end endgenerate
872		// }}}
873	
874		// o_valid
875		// {{{
876		initial	r_valid = 1'b0;
877		generate if (OPT_PIPELINED)
878		begin : GEN_DCD_VALID
879	
880			always @(posedge i_clk)
881			if (i_reset)
882				r_valid <= 1'b0;
883			else if (i_ce)
884				r_valid <= ((pf_valid)||(o_phase))&&(!o_ljmp);
885			else if (!i_stalled)
886				r_valid <= 1'b0;
887	
888		end else begin : GEN_DCD_VALID
889	
890			always @(posedge i_clk)
891			if (i_reset)
892				r_valid <= 1'b0;
893			else if (!i_stalled)
894				r_valid <= ((pf_valid)||(o_phase))&&(!o_ljmp);
895			else
896				r_valid <= 1'b0;
897	
898		end endgenerate
899	
900		assign	o_valid = r_valid;
901		// }}}
902	
903		assign	o_I = { {(32-22){r_I[22]}}, r_I[21:0] };
904	
905		// Make Verilator happy across all our various options
906		// {{{
907		// verilator coverage_off
908		// verilator lint_off  UNUSED
909		wire	possibly_unused;
910		assign	possibly_unused = &{ 1'b0, w_lock, w_ljmp, w_ljmp_dly,
911				insn_is_pipeable, w_cis_ljmp, i_pc[1:0], w_add };
912		// verilator lint_on  UNUSED
913		// verilator coverage_on
914		// }}}
