2135			`ASSERT(fc_lock == o_lock);
2136			`ASSERT(fc_wR  == o_wR);
2137			`ASSERT(fc_rA  == o_rA);
2138			`ASSERT(fc_rB  == o_rB);
2139			`ASSERT(fc_sim  == o_sim);
2140			`ASSERT(fc_sim_immv  == o_sim_immv);
2141			`ASSERT(fc_prepipe == insn_is_pipeable);
2142		end else
2143			`ASSERT((i_reset)||(!insn_is_pipeable));
2144	
2145		always @(*)
2146		if (o_phase)
2147			`ASSERT(r_nxt_half[14:0] == f_insn_word[14:0]);
2148	
2149		always @(posedge i_clk)
2150		if ((f_past_valid)&&(!$past(i_reset))&&(!i_reset)
2151			&&($past(i_ce))&&(o_valid))
2152		begin
2153			`ASSERT(((fc_illegal)
2154				||$past((i_illegal)&&(!o_phase))
2155				||$past((o_illegal)&&( o_phase)))== o_illegal);
2156		end
2157	
2158		always @(posedge i_clk)
2159		if ((!o_valid)||(o_illegal))
2160			`ASSERT(!insn_is_pipeable);
2161	
2162		generate if ((OPT_CIS)&&(OPT_EARLY_BRANCHING))
2163		begin
2164	
2165			always @(*)
2166			if ((o_valid)
2167					// LW
2168					&&(o_M)&&(o_op[2:0]==3'b010)
2169					// Zero immediate
2170					&&(o_zI)
2171					// Unconditional
2172					&&(o_cond[3])
2173					// From PC to PC
2174					&&(o_dcdR[5])&&(o_dcdB[5]))
2175			begin
2176				`ASSERT((o_ljmp)
2177					||((f_insn_word[31])&&(o_phase || o_illegal)));
2178			end else if (o_valid)
2179				`ASSERT(!o_ljmp);
2180	
2181		end endgenerate
2182		// }}}
2183	`endif // FORMAL
2184	// }}}
2185	endmodule
2186

